import Foundation

extension JSONDecoder {
    /// Decodes every TMDB response (snake_case keys).
    static var tmdb: JSONDecoder {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return decoder
    }
}

/// TMDB sends release dates as `"yyyy-MM-dd"`, an empty string, or nothing.
enum TMDBDate {
    private static let style = Date.ISO8601FormatStyle().year().month().day()

    static func parse(_ string: String) -> Date? {
        string.isEmpty ? nil : try? Date(string, strategy: style)
    }

    /// Four-digit year (UTC), e.g. "2010".
    static func year(of date: Date?) -> String? {
        guard let date else { return nil }
        return date.formatted(style.year()).prefix(4).description
    }
}

extension KeyedDecodingContainer {
    func decodeTMDBDate(forKey key: Key) throws -> Date? {
        guard let string = try decodeIfPresent(String.self, forKey: key) else { return nil }
        return TMDBDate.parse(string)
    }
}
EOF
cat > Movie.swift <<'EOF'
import Foundation

struct Movie: Identifiable, Hashable, Sendable {
    let id: Int
    let title: String
    let overview: String
    let posterPath: String?
    let backdropPath: String?
    let releaseDate: Date?
    let voteAverage: Double
    let voteCount: Int
    let genreIDs: [Int]

    var year: String? { TMDBDate.year(of: releaseDate) }
    var ratingText: String { String(format: "%.1f", voteAverage) }
}

extension Movie: Decodable {
    private enum CodingKeys: String, CodingKey {
        case id, title, overview, posterPath, backdropPath, releaseDate, voteAverage, voteCount
        case genreIDs = "genreIds"
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(Int.self, forKey: .id)
        title = try c.decode(String.self, forKey: .title)
        overview = try c.decodeIfPresent(String.self, forKey: .overview) ?? ""
        posterPath = try c.decodeIfPresent(String.self, forKey: .posterPath)
        backdropPath = try c.decodeIfPresent(String.self, forKey: .backdropPath)
        releaseDate = try c.decodeTMDBDate(forKey: .releaseDate)
        voteAverage = try c.decode(Double.self, forKey: .voteAverage)
        voteCount = try c.decode(Int.self, forKey: .voteCount)
        genreIDs = try c.decodeIfPresent([Int].self, forKey: .genreIDs) ?? []
    }
}
EOF
